('recipes/link-cannelloni-hackfleisch', 'recipes', '{"category": "main", "createdAt": "2026-11-01T19:50:00.000Z", "effort": null, "image": "7918e719526de714ad9eaae5d9ef44fe", "importId": "0c74575c0c294d28", "ingredients": [{"amount": 1, "foodId": "f-olivenoel", "name": "Olivenöl (Füllung)", "raw": "1 EL Olivenöl (Füllung)", "unit": "EL"}, {"amount": 1, "foodId": "f-zwiebel", "name": "Zwiebel (Füllung)", "raw": "1 kleine Zwiebel (Füllung)", "unit": null}, {"amount": 1, "foodId": "f-knoblauch", "name": "Knoblauch (Füllung)", "raw": "1 Knoblauchzehe (Füllung)", "unit": "Zehe"}, {"amount": 300, "foodId": null, "name": "Rinderhackfleisch", "raw": "300 g Rinderhackfleisch", "unit": "g"}, {"amount": 1, "foodId": "f-tomatenmark", "name": "Tomatenmark", "raw": "1 TL Tomatenmark", "unit": "TL"}, {"amount": 400, "foodId": null, "name": "Gehackte Tomaten", "raw": "400 g gehackte Tomaten (1 Dose)", "unit": "g"}, {"amount": 1, "foodId": null, "name": "Oregano", "raw": "1 TL Oregano, getrocknet", "unit": "TL"}, {"amount": null, "foodId": null, "name": "Salz und Pfeffer (Füllung)", "raw": "Salz und Pfeffer (Füllung)", "unit": null}, {"amount": 1, "foodId": "f-olivenoel", "name": "Olivenöl (Sauce)", "raw": "1 EL Olivenöl (Sauce)", "unit": "EL"}, {"amount": 1, "foodId": "f-zwiebel", "name": "Zwiebel (Sauce)", "raw": "1 kleine Zwiebel (Sauce)", "unit": null}, {"amount": 1, "foodId": "f-knoblauch", "name": "Knoblauch (Sauce)", "raw": "1 Knoblauchzehe (Sauce)", "unit": "Zehe"}, {"amount": 400, "foodId": null, "name": "Passierte Tomaten", "raw": "400 g passierte Tomaten", "unit": "g"}, {"amount": 1, "foodId": "f-zucker", "name": "Zucker", "raw": "1 TL Zucker", "unit": "TL"}, {"amount": null, "foodId": null, "name": "Italienische Kräuter", "raw": "Italienische Kräuter, getrocknet", "unit": null}, {"amount": null, "foodId": null, "name": "Salz und Pfeffer (Sauce)", "raw": "Salz und Pfeffer (Sauce)", "unit": null}, {"amount": 30, "foodId": "f-butter", "name": "Butter", "raw": "30 g Butter", "unit": "g"}, {"amount": 30, "foodId": "f-weizenmehl", "name": "Mehl", "raw": "30 g Mehl", "unit": "g"}, {"amount": 450, "foodId": "f-vollmilch-3-25", "name": "Milch", "raw": "450 ml Milch", "unit": "ml"}, {"amount": null, "foodId": null, "name": "Salz, Pfeffer, Muskat", "raw": "Salz, Pfeffer, frisch geriebene Muskatnuss", "unit": null}, {"amount": 12, "foodId": null, "name": "Cannelloni", "raw": "10–12 Cannelloni (ungekocht)", "unit": "Stück"}, {"amount": 150, "foodId": null, "name": "Mozzarella (gerieben)", "raw": "150 g geriebener Mozzarella", "unit": "g"}, {"amount": null, "foodId": null, "name": "Butter (Form)", "raw": "Butter zum Einfetten der Form", "unit": null}], "instructions": "Zwiebel und Knoblauch für die Füllung fein hacken und im Olivenöl glasig dünsten.\nHackfleisch krümelig anbraten, Tomatenmark kurz mitrösten, gehackte Tomaten, Salz, Pfeffer und Oregano zugeben. Offen einkochen, bis kaum noch Flüssigkeit übrig ist (ca. 15–20 Min.), dann abkühlen lassen. Die Füllung muss dick sein, sonst läuft Flüssigkeit aus.\nFür die Tomatensauce Zwiebel und Knoblauch fein würfeln, im Olivenöl glasig dünsten, passierte Tomaten, Zucker, Kräuter, Salz und Pfeffer zugeben und ca. 10 Min. leicht köcheln lassen.\nFür die Béchamel die Butter schmelzen, das Mehl kurz anschwitzen (keine Farbe). Die Milch nach und nach unter Rühren einarbeiten, mit Salz, Pfeffer und Muskat würzen und einige Minuten köcheln, bis sie leicht andickt. Bei Bedarf etwas Milch nachgießen.\nBackofen auf 180 °C Ober-/Unterhitze vorheizen.\nDie abgekühlte Füllung mit einem Löffel oder Spritzbeutel in die ungekochten Cannelloni füllen.\nForm einfetten, ein Drittel der Tomatensauce auf den Boden geben und die Cannelloni eng hineinlegen.\nRestliche Tomatensauce darüber verteilen (offene Enden bedecken), Béchamel gleichmäßig darauf geben und mit Mozzarella bestreuen.\nCa. 45 Min. backen, bis die Nudeln weich und der Käse goldgelb ist.\nCa. 10 Min. ruhen lassen und servieren.", "prepMinutes": 105, "servings": 2, "source": "https://www.einfachmalene.de/cannelloni-mit-hackfleisch-cremig-aus-dem-ofen/", "tags": "Ofengericht, Hackfleisch, Pasta", "title": "Cannelloni mit Hackfleisch, cremig aus dem Ofen", "titleKey": "cannelloni mit hackfleisch, cremig aus dem ofen", "updatedAt": "2026-11-01T19:50:00.000Z", "version": 1}'::jsonb),
('recipes/link-linsensalat', 'recipes', '{"category": "mittag", "createdAt": "2026-11-01T19:30:00.000Z", "effort": null, "image": "9dc7e0051789b9d8013023fcab885592", "importId": null, "ingredients": [{"amount": 400, "foodId": null, "name": "Braune Linsen (gekocht)", "raw": "400 g braune Linsen, gekocht", "unit": "g"}, {"amount": 1, "foodId": "f-gurke", "name": "Mini-Gurke", "raw": "1 Mini-Gurke", "unit": null}, {"amount": 1, "foodId": "f-paprika-rot", "name": "Paprika (rot)", "raw": "1 rote Paprikaschote", "unit": null}, {"amount": 1, "foodId": "f-zwiebel", "name": "Rote Zwiebel", "raw": "1 rote Zwiebel", "unit": null}, {"amount": 150, "foodId": "f-feta", "name": "Feta", "raw": "150 g Feta", "unit": "g"}, {"amount": 3, "foodId": null, "name": "Petersilie", "raw": "3 EL glatte Petersilie, gehackt", "unit": "EL"}, {"amount": 2, "foodId": null, "name": "Minze", "raw": "2 EL Minze, gehackt", "unit": "EL"}, {"amount": 4, "foodId": "f-olivenoel", "name": "Olivenöl", "raw": "4 EL Olivenöl", "unit": "EL"}, {"amount": 2, "foodId": null, "name": "Zitronensaft", "raw": "2 EL Zitronensaft", "unit": "EL"}, {"amount": 1, "foodId": null, "name": "Dijon-Senf", "raw": "1 TL Dijon-Senf", "unit": "TL"}, {"amount": 1, "foodId": "f-honig", "name": "Honig", "raw": "1 TL Honig", "unit": "TL"}, {"amount": 1, "foodId": "f-knoblauch", "name": "Knoblauch", "raw": "1 Knoblauchzehe, gehackt", "unit": "Zehe"}, {"amount": null, "foodId": null, "name": "Salz und Pfeffer", "raw": "Salz und Pfeffer", "unit": null}], "instructions": "Linsen abspülen und in eine Schüssel geben. Gurke in kleine Stücke schneiden, Paprika sehr fein würfeln, Zwiebel fein hacken und Feta klein schneiden. Alles zu den Linsen geben.\nDressing-Zutaten verrühren und zusammen mit Petersilie und Minze unter die Salatzutaten heben.", "nutrition": {"basis": "portion", "carbs": 26, "fat": 10, "kcal": 247, "protein": 15, "quality": "original"}, "prepMinutes": 15, "servings": 4, "source": "https://www.gaumenfreundin.de/linsensalat-einfach-und-schnell/", "tags": "vegetarisch, proteinreich, schnell", "title": "Linsensalat mit Feta und Minze", "titleKey": "linsensalat mit feta und minze", "updatedAt": "2026-11-01T19:30:00.000Z", "version": 1}'::jsonb),
('recipes/link-overnight-oats', 'recipes', '{"category": "fruehstueck", "createdAt": "2026-11-01T20:45:00.000Z", "effort": null, "image": "8f87740c9863680fa278ebd80a5ddf4e", "importId": "80f68b7979584fdc", "ingredients": [{"amount": 50, "foodId": "f-haferflocken", "name": "Haferflocken", "raw": "50 g Haferflocken", "unit": "g"}, {"amount": 150, "foodId": "f-vollmilch-3-25", "name": "Milch", "raw": "150 ml Milch (oder Hafermilch)", "unit": "ml"}, {"amount": 1, "foodId": null, "name": "Chiasamen (optional)", "raw": "1 EL Chiasamen (bei Belieben)", "unit": "EL"}, {"amount": 1, "foodId": null, "name": "Ahornsirup (optional)", "raw": "1 TL Ahornsirup (bei Belieben)", "unit": "TL"}, {"amount": 100, "foodId": null, "name": "Obst der Saison (Topping)", "raw": "100 g Obst der Saison (Topping)", "unit": "g"}], "instructions": "Haferflocken in ein Schraubglas geben. Nach Belieben 1 EL Chiasamen und 1 TL Ahornsirup dazugeben. Milch darübergießen, das Glas verschließen und über Nacht (ca. 6–8 Stunden, mindestens 2 Stunden) in den Kühlschrank stellen.\nAm nächsten Morgen kurz vor dem Essen das Obst als Topping daraufgeben.\nTipp der Seite: Bei Meal Prep das Topping erst kurz vor dem Servieren auflegen. Im Kühlschrank 3–4 Tage haltbar.", "nutrition": {"basis": "portion", "carbs": 42, "fat": 6, "kcal": 283, "protein": 13, "quality": "original"}, "prepMinutes": 5, "servings": 1, "source": "https://www.familienkost.de/rezept_overnight-oats-grundrezept.html", "tags": "vegetarisch, schnell, Meal Prep, ohne Kochen", "title": "Overnight Oats – Grundrezept", "titleKey": "overnight oats - grundrezept", "updatedAt": "2026-11-01T20:45:00.000Z", "version": 1}'::jsonb),
('recipes/link-quinoa-salat', 'recipes', '{"category": "mittag", "createdAt": "2026-11-01T19:30:00.000Z", "effort": null, "image": "e87f1905b38ef4ca015ac3a38c54d3e4", "importId": null, "ingredients": [{"amount": 150, "foodId": "f-quinoa-roh", "name": "Quinoa", "raw": "150 g Quinoa", "unit": "g"}, {"amount": 200, "foodId": "f-tomaten", "name": "Kirschtomaten", "raw": "200 g Kirschtomaten", "unit": "g"}, {"amount": 1, "foodId": "f-gurke", "name": "Minigurke", "raw": "1 Minigurke", "unit": null}, {"amount": 200, "foodId": null, "name": "Kichererbsen (Glas)", "raw": "200 g Kichererbsen (Glas)", "unit": "g"}, {"amount": 150, "foodId": "f-feta", "name": "Feta", "raw": "150 g Feta", "unit": "g"}, {"amount": 1, "foodId": null, "name": "Petersilie", "raw": "1 EL Petersilie, gehackt", "unit": "EL"}, {"amount": 3, "foodId": "f-olivenoel", "name": "Olivenöl", "raw": "3 EL Olivenöl", "unit": "EL"}, {"amount": 2, "foodId": null, "name": "Zitronensaft", "raw": "2 EL Zitronensaft, frisch gepresst", "unit": "EL"}, {"amount": 1, "foodId": "f-honig", "name": "Honig", "raw": "1 TL Honig", "unit": "TL"}, {"amount": null, "foodId": null, "name": "Salz und Pfeffer", "raw": "Salz und Pfeffer", "unit": null}], "instructions": "Quinoa in einem Sieb waschen und nach Packungsangabe kochen (laut Text der Seite ca. 15 Minuten).\nKirschtomaten halbieren, Minigurke würfeln, Kichererbsen abspülen und Feta zerbröseln.\nOlivenöl, Zitronensaft, Honig, Salz und Pfeffer zu einem Dressing verrühren.\nAlle Salatzutaten mit dem Dressing mischen und mit Petersilie bestreuen.\nHält sich 2–3 Tage im Kühlschrank.", "nutrition": {"basis": "portion", "carbs": 43, "fat": 13, "kcal": 342, "protein": 16, "quality": "original"}, "prepMinutes": 20, "servings": 4, "source": "https://www.gaumenfreundin.de/quinoa-salat-schnelles-rezept/", "tags": "vegetarisch, glutenfrei, proteinreich, schnell", "title": "Quinoa-Salat mit Feta und Kichererbsen", "titleKey": "quinoa-salat mit feta und kichererbsen", "updatedAt": "2026-11-01T19:30:00.000Z", "version": 1}'::jsonb),
